package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.Seconds;
import org.eclipse.rdf4j.sail.lmdb.ValueIds;
import org.eclipse.rdf4j.sail.lmdb.ValueStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.inlined.Values;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbNativeZeroFractionDateTimeTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void nativeDecodeAndSecondsAgreeWithTheCalendarDecoder() {
		LmdbNativeValueCodec codec = new LmdbNativeValueCodec(null);
		Seconds seconds = new Seconds();
		LmdbNativeFunctionLibrary.Entry entry = LmdbNativeFunctionLibrary.entry(seconds.getURI());
		assertThat(entry.inlineFastPath).isNotNull();
		for (CoreDatatype.XSD type : List.of(CoreDatatype.XSD.DATETIME, CoreDatatype.XSD.DATETIMESTAMP)) {
			for (String zone : List.of("Z", "+05:30", "-14:00")) {
				for (String fraction : List.of("", ".0", ".00", ".000", ".001", ".120", ".999")) {
					Literal literal = VF.createLiteral("2023-01-15T10:30:42" + fraction + zone, type);
					long id = Values.packLiteral(literal);
					assertThat(ValueIds.isInlined(id)).isTrue();
					assertThat(LmdbNativeValueCodec.toValue(codec.decode(id))).isEqualTo(literal);
					assertThat(LmdbNativeValueCodec.toValue(entry.inlineFastPath.apply(id)))
							.isEqualTo(seconds.evaluate(VF, literal));
				}
			}
		}
	}

	@Test
	void computedDateValuesHonorTheLegacyStoreCapability(@TempDir File directory) throws Exception {
		ValueStore store = new ValueStore(directory, new LmdbStoreConfig());
		try {
			LmdbNativeValueCodec codec = new LmdbNativeValueCodec(store);
			for (String fraction : List.of(".0", ".00", ".000", ".001")) {
				Literal literal = VF.createLiteral("2023-01-15T10:30:42" + fraction + "Z", CoreDatatype.XSD.DATETIME);
				LmdbNativeValueCodec.DecodedValue decoded = LmdbNativeValueCodec.fromValue(literal);
				long id = codec.packInlineId(decoded);
				if (fraction.equals(".0") || fraction.equals(".00")) {
					assertThat(id).isEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
				} else {
					assertThat(id).isEqualTo(Values.packLiteral(literal));
				}
				assertThat(LmdbNativeValueCodec.packInline(decoded, true, false, true))
						.isEqualTo(Values.packLiteral(literal));
			}
		} finally {
			store.close();
		}
	}
}
